import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse each string in xs as an integer and return the sum.

    Raises BadInput carrying the first string that is not an integer.
    An empty list sums to 0.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_parsed_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_negative_and_signs() -> None:
    assert sum_parsed(["-5", "+3", "10"]) == 8


def test_sum_parsed_whitespace_and_zero() -> None:
    assert sum_parsed([" 4 ", "0", "-0"]) == 4


def test_sum_parsed_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "abc", "3"])
    assert exc.value.text == "abc"


def test_sum_parsed_first_bad_wins() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "x", "y"])
    assert exc.value.text == "x"


def test_sum_parsed_rejects_float_and_empty_string() -> None:
    with pytest.raises(BadInput) as exc:
        sum_parsed(["1", "2.5"])
    assert exc.value.text == "2.5"
    with pytest.raises(BadInput) as exc2:
        sum_parsed([""])
    assert exc2.value.text == ""


def test_sum_parsed_large_values() -> None:
    big = 10**30
    assert sum_parsed([str(big), "1"]) == big + 1

